const burger = document.getElementById('burger');
const navLinks = document.getElementById('navLinks');
if (burger && navLinks) {
  burger.setAttribute('aria-expanded', 'false');
  burger.addEventListener('click', () => {
    const isOpen = navLinks.classList.toggle('open');
    burger.setAttribute('aria-expanded', String(isOpen));
  });
  navLinks.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {
    navLinks.classList.remove('open');
    burger.setAttribute('aria-expanded', 'false');
  }));
}

document.querySelectorAll('[data-tab-btn]').forEach(btn => {
  btn.addEventListener('click', () => {
    const tab = btn.getAttribute('data-tab-btn');
    document.querySelectorAll('[data-tab-btn]').forEach(b => {
      b.classList.toggle('active', b === btn);
      b.setAttribute('aria-selected', String(b === btn));
    });
    document.querySelectorAll('[data-tab-panel]').forEach(panel => {
      panel.classList.toggle('active', panel.getAttribute('data-tab-panel') === tab);
    });
  });
});

const path = location.pathname.split('/').pop() || 'index.html';
document.querySelectorAll('.nav-links a').forEach(a => {
  const href = a.getAttribute('href');
  if (href === path) a.classList.add('active');
});


// Planning Genesis automatique, avec dates et libellés adaptés à la langue sélectionnée.
const gwrLocaleMap = {fr:'fr-FR',en:'en-GB',es:'es-ES',it:'it-IT',ja:'ja-JP',zh:'zh-CN',de:'de-DE'};
const gwrScheduleText = {
  fr:{starts:'Début à 19 h', next:'Prochain rendez-vous', dateAt:'à 19 h'},
  en:{starts:'Starts at 7 PM', next:'Next show', dateAt:'at 7 PM'},
  es:{starts:'Comienza a las 19:00', next:'Próximo evento', dateAt:'a las 19:00'},
  it:{starts:'Inizio alle 19:00', next:'Prossimo appuntamento', dateAt:'alle 19:00'},
  ja:{starts:'開始 19:00', next:'次回の予定', dateAt:'19:00'},
  zh:{starts:'19:00 开始', next:'下次活动', dateAt:'19:00'},
  de:{starts:'Beginn um 19 Uhr', next:'Nächster Termin', dateAt:'um 19 Uhr'}
};
function renderGenesisSchedule(lang='fr') {
  const schedule = document.getElementById('genesisSchedule');
  const nextDateTargets = document.querySelectorAll('[data-next-genesis]');
  if (!schedule && !nextDateTargets.length) return;
  if (!gwrLocaleMap[lang]) lang = 'fr';
  const now = new Date();
  const parisText = now.toLocaleString('en-US', { timeZone: 'Europe/Paris' });
  const parisNow = new Date(parisText);
  const today = new Date(parisNow.getFullYear(), parisNow.getMonth(), parisNow.getDate());
  const weekday = today.getDay();
  let daysUntilThursday = (4 - weekday + 7) % 7;
  if (daysUntilThursday === 0 && (parisNow.getHours() > 19 || (parisNow.getHours() === 19 && parisNow.getMinutes() > 0))) daysUntilThursday = 7;
  const firstThursday = new Date(today);
  firstThursday.setDate(today.getDate() + daysUntilThursday);
  const fmt = new Intl.DateTimeFormat(gwrLocaleMap[lang], {timeZone:'Europe/Paris', weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const capitalize = value => value.charAt(0).toLocaleUpperCase(gwrLocaleMap[lang]) + value.slice(1);
  const phrases = gwrScheduleText[lang];
  const dates = [];
  for (let i=0;i<10;i++) { const d=new Date(firstThursday); d.setDate(firstThursday.getDate()+i*7); dates.push(d); }
  nextDateTargets.forEach(target => { target.textContent = `${capitalize(fmt.format(dates[0]))} ${phrases.dateAt}`; });
  if (schedule) {
    schedule.replaceChildren();
    dates.forEach((date,index) => {
      const card=document.createElement('div'); card.className='card';
      const top=document.createElement('div'); top.className='card-top gold';
      const body=document.createElement('div'); body.className='card-body';
      const title=document.createElement('strong'); title.textContent=`Genesis — ${capitalize(fmt.format(date))}`;
      const line=document.createElement('small'); line.className='muted'; line.textContent=phrases.starts;
      body.append(title,document.createElement('br'),line);
      if(index===0){const pill=document.createElement('span');pill.className='pill';pill.textContent=phrases.next;body.prepend(pill,document.createElement('br'));}
      card.append(top,body); schedule.append(card);
    });
  }
}


